      guest: {
        firstName: r.guest?.first_name || r.customer?.first_name || '',
        lastName: r.guest?.last_name || r.customer?.last_name || '',
        email: r.guest?.email || r.customer?.email || '',
        phone: r.guest?.phone || r.customer?.phone || '',
        guests: r.guest?.count || r.adults || 1
      },
      checkIn: r.checkin || r.arrival_date || '',
      checkOut: r.checkout || r.departure_date || '',
      totalPrice: r.total_price || r.price || 0,
      currency: r.currency || 'EUR',
      channel: 'Booking.com',
      raw: r
    }
  };
});

