const items = $input.all();
return items.map(item => {
  const reservation = item.json.original || item.json;
  const raw = item.json.content?.[0]?.text || item.json.text || '';
  let mail = { subject: 'Willkommen bei Move-in2Stay', body_text: '', body_html: '' };
  try {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) mail = { ...mail, ...JSON.parse(match[0]) };
  } catch (e) {}
  return { json: { ...reservation, mail } };
});

